ground truth:
#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;

    void serialise(auto& adaptor) const {
        adaptor(packet_id, username);
        adaptor & hexi::prefixed(scores);
        adaptor & hexi::null_terminated(metadata);
    }
};

std::vector<uint8_t> serialize_packet(const NetworkPacket& packet) {
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    stream.serialise(packet);

    return buffer;
}

test cases:
#include <gtest/gtest.h>
#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(NetworkPacket, Serialize) {
    NetworkPacket packet;
    packet.packet_id = 12345;
    packet.username = "testuser";
    packet.scores = {100, 200, 300, 400};
    packet.metadata = "test metadata";

    auto buffer = serialize_packet(packet);
    ASSERT_FALSE(buffer.empty());
    EXPECT_GT(buffer.size(), 0);
}

TEST(NetworkPacket, SerializeLongString) {
    NetworkPacket packet;
    packet.packet_id = 777;
    packet.username = "very_long_username_that_should_work_correctly";
    packet.scores = {1, 2, 3};
    packet.metadata = "metadata with special chars: !@#$%^&*()";

    auto buffer = serialize_packet(packet);
    ASSERT_FALSE(buffer.empty());
}

