std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a buffer adaptor for the source buffer
    // Note: We need to remove const for the adaptor, but we'll ensure read-only usage
    std::vector<uint8_t>& mutable_source = const_cast<std::vector<uint8_t>&>(source_buffer);
    hexi::buffer_adaptor adaptor(mutable_source);

    // Create a binary stream for reading
    hexi::binary_stream stream(adaptor);

    // Read the specified number of bytes
    std::vector<uint8_t> result(bytes_to_read);
    if (bytes_to_read > 0) {
        stream.get(result.data(), bytes_to_read);
    }

    return result;
}

