#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> peek_buffer_data(const std::vector<uint8_t>& buffer, size_t bytes_to_peek) {
    std::vector<uint8_t> temp_buffer = buffer;
    hexi::buffer_adaptor adaptor(temp_buffer);

    std::vector<uint8_t> result(bytes_to_peek);
    adaptor.copy(result.data(), bytes_to_peek);

    return result;
}

test cases:
#include <gtest/gtest.h>
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(BufferAdaptor, PeekData) {
    std::vector<uint8_t> buffer = {1, 2, 3, 4, 5, 6, 7, 8};

    auto peeked = peek_buffer_data(buffer, 3);

    EXPECT_EQ(3, peeked.size());
    EXPECT_EQ(1, peeked[0]);
    EXPECT_EQ(2, peeked[1]);
    EXPECT_EQ(3, peeked[2]);
}

TEST(BufferAdaptor, PeekDoesNotConsume) {
    std::vector<uint8_t> buffer = {10, 20, 30, 40};

    auto first_peek = peek_buffer_data(buffer, 2);
    auto second_peek = peek_buffer_data(buffer, 2);

    EXPECT_EQ(first_peek, second_peek);
    EXPECT_EQ(10, first_peek[0]);
    EXPECT_EQ(20, first_peek[1]);
}

TEST(BufferAdaptor, PeekAllData) {
    std::vector<uint8_t> buffer = {100, 200, 150};

    auto peeked = peek_buffer_data(buffer, buffer.size());

    EXPECT_EQ(buffer, peeked);
}

