ground truth:
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);

    // Check available space using free()
    size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + items.size() * sizeof(uint32_t);
    if (adaptor.free() < required_space) {
        return false;
    }

    // Get write pointer
    uint8_t* write_ptr = adaptor.write_ptr();

    // Use binary_stream to write data
    hexi::binary_stream stream(adaptor);

    stream << header;
    uint32_t count = static_cast<uint32_t>(items.size());
    stream << count;
    stream << items;  // operator<< internally calls write_container

    return true;
}

