#include <hexi/dynamic_buffer.h>
#include <vector>
#include <cstdint>

template<size_t block_size = 1024>
std::vector<uint8_t> peek_data_from_buffer(const hexi::dynamic_buffer<block_size>& buffer, size_t bytes_to_peek) {
    // Create a vector to hold the peeked data
    std::vector<uint8_t> result;

    // If there's nothing to peek, return empty vector
    if (bytes_to_peek == 0) {
        return result;
    }

    // Resize the vector to hold the requested number of bytes
    result.resize(bytes_to_peek);

    // Use the buffer's copy method to peek at data without advancing read pointer
    buffer.copy(result.data(), bytes_to_peek);

    return result;
}
```

