#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(Endian, ConvertWithEnumBigToNative) {
    uint32_t value = 0x78563412; // Assume big endian

    auto result = convert_with_enum<hexi::endian::conversion::big_to_native>(value);
    auto back = convert_with_enum<hexi::endian::conversion::native_to_big>(result);

    EXPECT_EQ(value, back);
}

TEST(Endian, ConvertWithEnumLittleToNative) {
    uint32_t value = 0x12345678; // Assume little endian

    auto result = convert_with_enum<hexi::endian::conversion::little_to_native>(value);
    auto back = convert_with_enum<hexi::endian::conversion::native_to_little>(result);

    EXPECT_EQ(value, back);
}

TEST(Endian, ConvertWithEnumNativeToBig) {
    uint32_t value = 0x12345678;

    auto result = convert_with_enum<hexi::endian::conversion::native_to_big>(value);
    auto back = convert_with_enum<hexi::endian::conversion::big_to_native>(result);

    EXPECT_EQ(value, back);
}

