Looking at the code fragments, I can see that `hexi::file_buffer` is a class that wraps file operations. Based on the interface shown in the fragments, here's the complete implementation:

```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return {};
    }

    std::vector<uint8_t> data(bytes_to_read);
    buffer.read(reinterpret_cast<char*>(data.data()), bytes_to_read);

    if (!buffer) {
        return {};
    }

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return {};
    }

    std::vector<uint8_t> data(bytes_to_preview);

    // Read the data to preview
    buffer.read(reinterpret_cast<char*>(data.data()), bytes_to_preview);

    if (!buffer) {
        return {};
    }

    return data;
}

void write_file_data(const std::filesystem::path& file_path, const std::vector<uint8_t>& data) {
    hexi::file_buffer buffer(file_path, hexi::file_buffer::mode::write);
    if (!buffer) {
        return;
    }

    buffer.write(reinterpret_cast<const char*>(data.data()), data.size());
    buffer.flush();
}

size_t get_file_size(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return 0;
    }

    // Read until EOF to determine size
    std::vector<uint8_t> temp_buffer(4096);
    size_t total_size = 0;

    while (buffer) {
        size_t bytes_read = buffer.read(reinterpret_cast<char*>(temp_buffer.data()), temp_buffer.size());
        total_size += bytes_read;
        if (bytes_read < temp_buffer.size()) {
            break; // Reached EOF
        }
    }

    return total_size;
}
```

However, looking more carefully at the `file_buffer` interface, I notice it might have a `size()` method or similar functionality. Let me provide a more efficient implementation based on the actual interface:

```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return {};
    }

    std::vector<uint8_t> data(bytes_to_read);
    size_t bytes_read = buffer.read(reinterpret_cast<char*>(data.data()), bytes_to_read);

    if (bytes_read != bytes_to_read) {
        data.resize(bytes_read);
    }

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    // Since file_buffer doesn't support seeking, we need to read and then re-open
    // to maintain the original position. However, without seeking support,
    // preview is essentially the same as read for this implementation.
    return read_file_data(file_path, bytes_to_preview);
}

void write_file_data(const std::filesystem::path& file_path, const std::vector<uint8_t>& data) {
    hexi::file_buffer buffer(file_path, hexi::file_buffer::mode::write);
    if (!buffer) {
        return;
    }

    buffer.write(reinterpret_cast<const char*>(data.data()), data.size());
    buffer.flush();
}

size_t get_file_size(const std::filesystem::path& file_path) {
    // Use standard filesystem library to get file size
    try {
        return std::filesystem::file_size(file_path);
    } catch (const std::filesystem::filesystem_error&) {
        return 0;
    }
}
```

The second implementation is more practical since:
1. `preview_file_data` can't truly preview without seeking support
2. `get_file_size` uses the standard filesystem library which is more reliable
3. It properly handles partial reads in `read_file_data`

