int32_t read_int32_from_file(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        // Handle file open failure - you might want to throw an exception
        return 0;
    }

    int32_t value = 0;
    buffer.read(&value);

    if (!buffer) {
        // Handle read failure - you might want to throw an exception
        return 0;
    }

    return value;
}

