Header peek_header_without_reading(const std::vector<uint8_t>& buffer) {
    // Create a read adaptor for the buffer
    hexi::pmc::buffer_read_adaptor adaptor(const_cast<std::vector<uint8_t>&>(buffer));

    Header header;

    // Use copy() to peek at header without advancing read cursor
    adaptor.copy(&header, sizeof(Header));

    // Use read_ptr() to verify pointer position (read pointer should not move after copy)
    const std::byte* ptr_before = adaptor.read_ptr();

    // Verify the data without advancing read cursor by calling copy again
    Header verify_header;
    adaptor.copy(&verify_header, sizeof(Header));

    const std::byte* ptr_after = adaptor.read_ptr();

    // Ensure read pointer didn't move (copy should not advance cursor)
    // In a real implementation, you might want to assert this
    // assert(ptr_before == ptr_after);

    return header;
}

std::vector<uint8_t> peek_then_conditionally_read(const std::vector<uint8_t>& buffer) {
    // Create a read adaptor for the buffer
    hexi::pmc::buffer_read_adaptor adaptor(const_cast<std::vector<uint8_t>&>(buffer));

    std::vector<uint8_t> result;

    // Peek at first byte using copy()
    uint8_t first_byte;
    adaptor.copy(&first_byte, sizeof(first_byte));

    // Conditionally read based on the peeked value
    if (first_byte == 0xFF) {
        // If first byte is 0xFF, read the entire buffer
        result.resize(buffer.size());
        adaptor.read(result.data(), buffer.size());
    } else if (first_byte >= 0x80) {
        // If first byte is >= 0x80, read first 4 bytes
        result.resize(4);
        adaptor.read(result.data(), 4);
    } else {
        // Otherwise, read just the first byte
        result.resize(1);
        adaptor.read(result.data(), 1);
    }

    return result;
}
