};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    // Create a dynamic buffer to hold the serialized data
    hexi::dynamic_buffer buffer;

    // Create a binary stream writer for the buffer
    hexi::binary_stream_writer writer(buffer);

    // Serialize message_id with endianness conversion
    uint32_t be_message_id = hexi::endian::native_to_big(packet.message_id);
    writer.write(be_message_id);

    // Serialize data_values vector with endianness conversion
    // First write the count of elements
    uint32_t data_count = static_cast<uint32_t>(packet.data_values.size());
    uint32_t be_data_count = hexi::endian::native_to_big(data_count);
    writer.write(be_data_count);

    // Write each element with endianness conversion
    for (uint16_t value : packet.data_values) {
        uint16_t be_value = hexi::endian::native_to_big(value);
        writer.write(be_value);
    }

    // Serialize checksum with endianness conversion
    uint32_t be_checksum = hexi::endian::native_to_big(packet.checksum);
    writer.write(be_checksum);

